import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { LiveStatus } from '../types'
import { PacmanLane } from './logic/pacman-lane'
import type { LaneCell } from './logic/pacman-lane'
import { Palette } from './logic/palette'

const isWorking = atom({ plugin: 'pacman-band', key: 'isWorking' } as const, false)
const liveAgents = atom({ plugin: 'pacman-band', key: 'liveAgents' } as const, 0)
const frame = atom({ plugin: 'pacman-band', key: 'frame' } as const, 0)
const isLightTheme = atom({ plugin: 'pacman-band', key: 'isLightTheme' } as const, false)

type $ = EngineInterface

// Pac-Man steps a column each tick; the timer runs only while something is busy.
const FRAME_MS = 125
// How long an answered agent's ghost stays frightened at his mouth.
const EAT_MS = 1_500
const LIVE_STATUSES: readonly string[] = ['pending', 'running', 'waiting'] satisfies LiveStatus[]
const RESET_REASONS = ['clear', 'resume']

const lane = new PacmanLane()
let timer: Timer | undefined
let eatUntil = 0
// Agents that answered: left out of the count even while the list still shows them running.
const answered = new Set<string>()

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    void refreshTheme($).catch(ignoreFailure)

    return next(e)
  })

  on('config.set', { key: 'theme' }, async ($, e, next) => {
    const set = await next(e)
    await refreshTheme($).catch(ignoreFailure)

    return set
  })

  on('session.end', async ($, e, next) => {
    if (RESET_REASONS.includes(e.reason)) {
      await update($, isWorking, () => false)
      await update($, liveAgents, () => 0)
      eatUntil = 0
      answered.clear()
      await ensureTimer($)
    }

    return next(e)
  })

  // turn.start carries the person's prompt: the main agent's turns only.
  on('turn.start', async ($, e, next) => {
    await update($, isWorking, () => true)
    await ensureTimer($)

    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const spawned = await next(e)
    await refreshAgents($).catch(ignoreFailure)

    return spawned
  })

  on('turn.complete', async ($, e, next) => {
    const completed = await next(e)
    if (e.agentId === undefined) {
      await update($, isWorking, () => false)
    } else {
      // Its ghost, eaten.
      eatUntil = (await $.clock.now()) + EAT_MS
      answered.add(e.agentId)
      await refreshAgents($).catch(ignoreFailure)
    }
    await ensureTimer($)

    return completed
  })

  // A row of its own above whatever the other plugins draw, so it sits beside any band.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || !(await isBusy($))) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const colors = new Palette(await read($, isLightTheme))
    // A column spare: an icon the font draws two wide cannot wrap the row.
    const cells = lane.cells(
      Math.max(0, e.props.bodyColumns - 1),
      await read($, frame),
      await read($, liveAgents),
      (await $.clock.now()) < eatUntil,
    )
    const below = await next(e)

    return (
      <Box flexDirection="column">
        <Box>
          {cells.map(cell => (
            <Text bold={cell.kind !== 'dot' || undefined} color={laneColor(colors, cell)}>
              {cell.text}
            </Text>
          ))}
        </Box>
        {below}
      </Box>
    )
  })
}

async function isBusy($: $): Promise<boolean> {
  return (await read($, isWorking)) || (await read($, liveAgents)) > 0 || (await $.clock.now()) < eatUntil
}

async function refreshAgents($: $) {
  const live = (await $.agent.list()).filter(agent => LIVE_STATUSES.includes(agent.status) && !answered.has(agent.id)).length
  await update($, liveAgents, () => live)
  await ensureTimer($)
}

async function ensureTimer($: $) {
  const busy = await isBusy($)
  if (busy && timer === undefined) {
    timer = $.clock.every(FRAME_MS, () => void tick($).catch(ignoreFailure))
  } else if (!busy && timer !== undefined) {
    timer.cancel()
    timer = undefined
  }
}

// Each tick asks afresh whether anything is still busy, so the timer stops by itself.
async function tick($: $) {
  await update($, frame, n => n + 1)
  await ensureTimer($)
}

async function refreshTheme($: $) {
  const theme = (await $.config.list()).find(row => row.key === 'theme')?.value
  const isLight = typeof theme === 'string' && theme.startsWith('light')
  if ((await read($, isLightTheme)) !== isLight) await update($, isLightTheme, () => isLight)
}

function laneColor(colors: Palette, cell: LaneCell): string {
  if (cell.kind === 'pac') return colors.color('pac')
  if (cell.kind === 'ghost') return colors.ghost(cell.index ?? 0)
  return colors.color(cell.kind === 'scared' ? 'scared' : 'dim')
}

function ignoreFailure() {}

