// Swap these for what the terminal's font draws one column wide (the probe shows which).
// Material Design's pac_man from the Nerd Font: ᗧ fell back to a font that drew it as ɑ.
export const PAC_OPEN = '\u{f0baf}'
export const PAC_SHUT = '●'
export const GHOST = '\u{f02a0}'
const DOT = '·'

export type LaneCell = { text: string; kind: 'pac' | 'ghost' | 'scared' | 'dot' | 'empty'; index?: number }

const MAX_GHOSTS = 4
const GHOST_GAP = 3
const DOT_EVERY = 2

// The band while Claude works: Pac-Man crossing left to right a column a frame, eating the
// dots before him, a ghost for each agent or job still out running ahead of him.
export class PacmanLane {
  // A cell a column. isEating puts a frightened ghost at his mouth, the others a column on.
  cells(columns: number, frame: number, ghosts: number, isEating: boolean): LaneCell[] {
    if (columns <= 0) return []
    const at = frame % columns
    // The dots lie on fixed columns, so they wait for him rather than move with him.
    const cells: LaneCell[] = Array.from({ length: columns }, (_, column) =>
      column > at && column % DOT_EVERY === 0 ? { text: DOT, kind: 'dot' } : { text: ' ', kind: 'empty' },
    )
    const place = (offset: number, cell: LaneCell) => {
      cells[(at + offset) % columns] = cell
    }
    const shift = isEating ? 1 : 0
    for (let i = 0; i < Math.min(ghosts, MAX_GHOSTS); i++) place(GHOST_GAP * (i + 1) + shift, { text: GHOST, kind: 'ghost', index: i })
    if (isEating) place(1, { text: GHOST, kind: 'scared', index: 0 })
    place(0, { text: frame % 2 === 0 ? PAC_OPEN : PAC_SHUT, kind: 'pac' })

    return cells
  }
}

