export type Role = 'pac' | 'scared' | 'dim'

// Catppuccin: Mocha on a dark theme, Latte on a light one.
const MOCHA: Record<Role, string> = { pac: '#f9e2af', scared: '#89b4fa', dim: '#6c7086' }
const LATTE: Record<Role, string> = { pac: '#df8e1d', scared: '#1e66f5', dim: '#9ca0b0' }
// Blinky, Pinky, Inky and Clyde; Pinky in mauve, as workbench keeps pink for whose turn it is.
const MOCHA_GHOSTS = ['#f38ba8', '#cba6f7', '#94e2d5', '#fab387']
const LATTE_GHOSTS = ['#d20f39', '#8839ef', '#179299', '#fe640b']

export class Palette {
  private readonly colors: Record<Role, string>
  private readonly ghosts: readonly string[]

  constructor(isLight: boolean) {
    this.colors = isLight ? LATTE : MOCHA
    this.ghosts = isLight ? LATTE_GHOSTS : MOCHA_GHOSTS
  }

  color(role: Role): string {
    return this.colors[role]
  }

  // The ghosts in turn, round again past the fourth.
  ghost(index: number): string {
    return this.ghosts[index % this.ghosts.length] ?? this.colors.pac
  }
}

