// A sub-agent's list status that still counts as out: a ghost.
export type LiveStatus = 'pending' | 'running' | 'waiting'

declare module 'claude-code' {
  interface PluginState {
    'pacman-band': {
      // A main turn is running.
      isWorking: boolean
      // Sub-agents not yet answered: a ghost each.
      liveAgents: number
      frame: number
      // The /config theme is a light one: Latte, not Mocha.
      isLightTheme: boolean
    }
  }
}
